import subprocess

class GitWrapper:
    def __init__(self, repository_path):
        self.repository_path = repository_path

    def clone(self, repo_url):
        try:
            subprocess.run(["git", "clone", repo_url, self.repository_path], check=True)
            print(f"Cloned repository from {repo_url}")
        except subprocess.CalledProcessError as e:
            print(f"Failed to clone repository: {e}")

    def add(self, file_path):
        try:
            subprocess.run(["git", "add", file_path], cwd=self.repository_path, check=True)
            print(f"Added {file_path} to staging area")
        except subprocess.CalledProcessError as e:
            print(f"Failed to add file: {e}")

    def commit(self, message):
        try:
            subprocess.run(["git", "commit", "-m", message], cwd=self.repository_path, check=True)
            print("Committed changes with message:", message)
        except subprocess.CalledProcessError as e:
            print(f"Failed to commit changes: {e}")

    def push(self, remote_name="origin", branch_name="main"):
        try:
            subprocess.run(["git", "push", remote_name, branch_name], cwd=self.repository_path, check=True)
            print("Pushed changes to remote repository")
        except subprocess.CalledProcessError as e:
            print(f"Failed to push changes: {e}")

    def pull(self, remote_name="origin", branch_name="main"):
        try:
            subprocess.run(["git", "pull", remote_name, branch_name], cwd=self.repository_path, check=True)
            print("Pulled changes from remote repository")
        except subprocess.CalledProcessError as e:
            print(f"Failed to pull changes: {e}")
```

**Explanation**:
This Python class `GitWrapper` provides a simple interface for common Git operations such as cloning, adding files, committing, pushing, and pulling. Each method executes a corresponding Git command with error handling using the `subprocess.run()` function from the Python standard library. This ensures that any errors during the execution of Git commands are caught and printed to help with debugging or providing feedback on the operation's success or failure.
